window.__BUNDLE__={"generatedAt":"2026-08-31T06:04:16.133164+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-08-24","archiveCutoff":"2021-09-01","addedToday":247,"addedThisRun":247,"fetchStats":{"hf":195,"arxiv":1288,"total":1483},"freshness":{"latestPaperDate":"2026-08-31","latestPublishedDate":"2026-08-31","latestBatchCount":211,"newInLast24h":247,"newInLast48h":247},"historyTotal":9917,"topicCounts":{"Multi-Agent":1749,"Evaluation":5095,"Planning":879,"Memory":220,"Code Agent":499,"Interpretability":347,"Agentic RAG":969,"Agentic Search":1180,"RL for LLM":738,"Reasoning":3094,"Hallucination":602,"Post-Training":1387,"Alignment":1326,"World Model":111,"Tool Use":1031,"Agent Safety":2007,"Computer Use":208,"Reflection":426,"VLM Training":497,"LLM Training":1074,"Fine-tuning":1439,"Multimodal Agent":62,"Agent Framework":636,"Error Attribution":87,"Data Engine":211},"count":36,"recentTotal":1889,"archiveCount":0,"archiveTotal":8028,"sources":{"hf":27,"arxiv":1862,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"title":"Code as Worlds: Agentic Discovery of Executable World Representations for Physical Reasoning","id":"arxiv:2608.27549","submittedDate":"2026-08-27","topics":["VLM Training","Reasoning"],"source":"hf","tags":["VLM Training","Reasoning"],"authors":["Hanyang Wang","Yimo Cai","Weiliang Chen","Jiawei Chi","Haowen Sun","Qiyu Dai","Yi-Hsin Hung","Xingzhuo Guo","Jinshan Ren","Runmao Yao","Ziwei Liu","Mingsheng Long","Yueqi Duan","Jun Gao","Jiangran Lyu","Fangfu Liu","Jialong Wu"],"upvotes":23,"arxiv":"https://arxiv.org/abs/2608.27549","url":"https://arxiv.org/abs/2608.27549","pdf":"https://arxiv.org/pdf/2608.27549.pdf","date":"2026-08-31","hfUrl":"https://huggingface.co/papers/2608.27549","announceDate":"2026-08-31","abstract":"Physical understanding and reasoning depend on forming compact and generalizable representations of the world. While modern vision-language models can recognize and explain diverse physical events, they often lack explicit representations of the underlying mechanisms-such as object states, physical parameters, and governing dynamics-needed for reliably reasoning how the world evolves and responds to interventions. In this work, we introduce Code-as-World, a paradigm that represents physical worlds through executable world representations. By expressing physical composition, dynamic evolution, and visual appearance as executable code, Code-as-World provides a compact, quantitatively grounded, and controllable abstraction of the physical world. To construct such representations from multimodal observations, such as natural-language descriptions or real-world videos, we develop an agentic d"},{"title":"Beyond Data Scaling: Representation-Centric Continued Pre-training for Vision-Language-Action Models","id":"arxiv:2608.27550","submittedDate":"2026-08-27","topics":["LLM Training","VLM Training","Fine-tuning"],"source":"hf","tags":["LLM Training","VLM Training","Fine-tuning"],"authors":["Senqiao Yang","Chengyao Wang","Yuxin Chen","Zixuan Wang","Longxiang Tang","Haokun Gui","Jinhui Ye","Changsheng Lu","Xiaoyang Wu","Mingkang Zhu","Pengguang Chen","Shu Liu","Zhuotao Tian","Hengshuang Zhao","Bei Yu","Jiaya Jia"],"upvotes":19,"arxiv":"https://arxiv.org/abs/2608.27550","url":"https://arxiv.org/abs/2608.27550","pdf":"https://arxiv.org/pdf/2608.27550.pdf","date":"2026-08-31","hfUrl":"https://huggingface.co/papers/2608.27550","announceDate":"2026-08-31","abstract":"Scaling robot data is crucial for building generalist Vision-Language-Action (VLA) models, yet robot trajectories are harder to scale than web-scale image-text data because embodied collection is costly and sparsely covers the physical world. This makes representation quality a central bottleneck: under a fixed robot-data budget, continued pre-training must turn limited trajectories into transferable visual-action knowledge rather than merely fit actions. We propose VLAct, a VLA-oriented VLM backbone trained on broad, heterogeneous, multi-embodiment robot data before task-specific fine-tuning. VLAct preserves the broad VLM prior and encourages shared action semantics across embodiments through VLM-prior preservation, multi-head continuous action co-supervision, and a partially unified cross-embodiment action layout, while allowing task-specific action heads during fine-tuning. Across sim"},{"title":"ContextPilot: Teaching Agents for Proactive Context Management via Fine-grained RL","id":"arxiv:2608.28476","submittedDate":"2026-08-28","topics":["Reasoning","Planning","Memory","Evaluation"],"source":"hf","tags":["Reasoning","Planning","Memory","Evaluation"],"authors":["Zhuoshi Pan","Qizhi Pei","Junru Lu","Honglin Lin","H. Vicky Zhao","Di Yin","Xing Sun"],"upvotes":16,"arxiv":"https://arxiv.org/abs/2608.28476","url":"https://arxiv.org/abs/2608.28476","pdf":"https://arxiv.org/pdf/2608.28476.pdf","date":"2026-08-31","hfUrl":"https://huggingface.co/papers/2608.28476","announceDate":"2026-08-31","abstract":"Long-horizon agentic tasks require large language models (LLMs) to iteratively retrieve, integrate, and maintain dispersed information across multi-turn interactions, but preserving all interaction histories leads to a continuously growing working context. Recent proactive context management methods allow models to edit their own working context with specialized tools, yet they still face three key limitations: (1) a limited toolset restricted to search, deletion, and summarization, with no support for global planning, long-term memory, and adaptive compression; (2) inefficient exploration that treats context management actions uniformly despite their heterogeneous impacts on final outcomes; and (3) coarse-grained credit assignment that assigns the final trajectory-level reward to all intermediate context editing actions during RL. To bridge these gaps, we introduce ContextPilot, a proac"},{"title":"Blind Men and the Elephant: Probing the Epistemic Myopia of LLMs under Long-Tail Divergent Knowledge","id":"arxiv:2608.28478","submittedDate":"2026-08-28","topics":["Reasoning","Evaluation"],"source":"hf","tags":["Reasoning","Evaluation"],"authors":["Zhuoshi Pan","Junru Lu","Yan Qian","H. Vicky Zhao","Di Yin","Xing Sun"],"upvotes":11,"arxiv":"https://arxiv.org/abs/2608.28478","url":"https://arxiv.org/abs/2608.28478","pdf":"https://arxiv.org/pdf/2608.28478.pdf","date":"2026-08-31","hfUrl":"https://huggingface.co/papers/2608.28478","announceDate":"2026-08-31","abstract":"Factual question answering (QA) typically assumes a single canonical answer, obscuring whether large language models (LLMs) retain divergent accounts of long-tail facts. To address this gap, we introduce ElephantBench, a closed-book knowledge probe comprising 1,094 questions generated through an auditable graph-based pipeline. The pipeline retrieves related documents from a low-exposure web corpus, identifies naturally occurring disagreements, and converts them into multi-account QA records. Each answer is verified against the originating documents and authoritative public web sources and is then reviewed by human annotators. Across 32 models, even the strongest model recovers both accounts on only 52.4% of questions, while on nearly all remaining questions it recalls one account but omits the other. Scaling model size and inference-time reasoning improve recall but do not eliminate this"},{"title":"Rubric-to-Code Credit Assignment for Reinforcement Learning","id":"arxiv:2608.27906","submittedDate":"2026-08-28","topics":["Post-Training","LLM Training","Evaluation"],"source":"hf","tags":["Post-Training","LLM Training","Evaluation"],"authors":["Rui Jin","Jikai Chen","Yihan Chen","Hao Zhou","Demin Zhu","Kaichen Yang","Dong Wang","Chenyi Zhuang"],"upvotes":3,"arxiv":"https://arxiv.org/abs/2608.27906","url":"https://arxiv.org/abs/2608.27906","pdf":"https://arxiv.org/pdf/2608.27906.pdf","date":"2026-08-31","hfUrl":"https://huggingface.co/papers/2608.27906","announceDate":"2026-08-31","abstract":"Interactive web application generation requires models to produce usable HTML, CSS, and JavaScript applications from natural language requests. Unlike conventional code generation, application quality depends on multiple user-facing functional requirements, each often tied to localized code regions such as event handlers, state updates, DOM fragments, or CSS selectors. Standard GRPO collapses these structured outcomes into a single sequence-level reward and applies the resulting advantage uniformly to all tokens, weakening credit assignment. We propose \\textbf{Rubric-to-Code Credit Assignment} (RCCA), a reinforcement learning framework that converts rubric-level functional feedback into localized optimization signals over generated code. RCCA builds training tasks around explicit functional rubrics, uses a hierarchical reward to separate format, source-code, runtime, and functional failu"},{"title":"ReToolSQL: Agentic Reinforcement Learning for Robust Text-to-SQL","id":"arxiv:2608.27796","submittedDate":"2026-08-28","topics":["LLM Training","Tool Use","Reasoning","Evaluation","Fine-tuning","Reflection","RL for LLM"],"source":"arxiv","tags":["LLM Training","Tool Use","Reasoning","Evaluation","Fine-tuning"],"authors":["Pratik Kakkar","Chandra Dhir","Ravi Shankar","Pareekshit Reddy Gaddam","Anup Shirgaonkar"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27796","url":"https://arxiv.org/abs/2608.27796","pdf":"https://arxiv.org/pdf/2608.27796.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Recent work has shown that reinforcement learning from execution feedback can substantially improve text-to-SQL performance, often enabling smaller models to match or exceed much larger systems. However, most existing approaches treat SQL generation as a single-turn task, limiting the model's ability to recover from errors through iterative refinement. We present ReToolSQL, a two-stage training framework for text-to-SQL that combines (i) a supervised warm-start on rejection-sampled reasoning traces with (ii) agentic reinforcement fine-tuning (RFT) over multi-turn tool-use trajectories. The key insight is that the two stages act on complementary axes, the supervised fine-tuning (SFT) on verified privileged-teacher traces expands the set of solvable questions (raising pass@k coverage on the hardest cases), while RFT converts that expanded capability into higher single-pass accuracy by teac"},{"title":"Learning to Use Tools: Reinforcement Learning for Tool-Integrated Mathematical Reasoning","id":"arxiv:2608.28447","submittedDate":"2026-08-28","topics":["Post-Training","LLM Training","Tool Use","Reasoning","Evaluation","Fine-tuning","RL for LLM"],"source":"arxiv","tags":["Post-Training","LLM Training","Tool Use","Reasoning","Evaluation"],"authors":["Minghui Xu","Zi Wang"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.28447","url":"https://arxiv.org/abs/2608.28447","pdf":"https://arxiv.org/pdf/2608.28447.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Current large language models (LLMs) increasingly benefit from external tool integration, especially for tasks requiring reliable computation and verification. Motivated by this, we study calculator tool calling for improving mathematical reasoning on the Countdown task. We first analyze reasoning failures and find that calculation errors account for a substantial portion of incorrect responses. We then construct supervised fine-tuning datasets to teach the model useful tool-use patterns and how to interpret returned outputs. Building on this tool-formatted policy, we apply several on-policy reinforcement learning methods, including RLOO, RLOO++, GRPO, and DAPO, using automatically verifiable final-answer rewards. To enable a more reliable evaluation, we construct a fresh 1,024-problem held-out Countdown benchmark with no exact overlap with the training data. Our results show that calcul"},{"title":"WeAgent-MMSearch: Native Text-Vision Interaction for Multimodal Search Agents","id":"arxiv:2608.28062","submittedDate":"2026-08-28","topics":["Agentic Search","Post-Training","Reasoning","Planning","Evaluation","Multimodal Agent"],"source":"arxiv","tags":["Agentic Search","Post-Training","Reasoning","Planning","Evaluation"],"authors":["Zongkai Liu","Hui Zhang","Liqiang Niu","Zhen Cao","Han Li","Juntao Liu","Wenchao Chen","Chengduo Zhao","Chao Yu","Fandong Meng"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.28062","url":"https://arxiv.org/abs/2608.28062","pdf":"https://arxiv.org/pdf/2608.28062.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Multimodal search agents extend parametric knowledge with newly emerging and long-tail evidence from the open web. Yet many existing agentic search environments often expose retrieved evidence only as text and omit tool-returned images from subsequent context, reducing visually grounded trajectories to text-only reasoning. Long-horizon interaction also compounds tool-call, response-length, timeout, and budget failures, which can discard salvageable trajectories, waste rollout computation, and disturb policy updates. To address these issues, we introduce WeAgent-Harness, a multimodal agentic harness that supports native text-vision interaction and runtime recovery. Retrieved images receive persistent disk references, allowing the model to inspect, process, and cite them throughout the trajectory. Based on this harness, we develop WeAgent-MMSearch, an integrated system spanning data constr"},{"title":"See, Hypothesize, Validate: Multimodal Agentic Framework for Discovering Governing PDEs","id":"arxiv:2608.27869","submittedDate":"2026-08-28","topics":["VLM Training","Reasoning","Hallucination","Reflection","Multimodal Agent"],"source":"arxiv","tags":["VLM Training","Reasoning","Hallucination","Reflection","Multimodal Agent"],"authors":["Sarang Manoj Pekhale","Amartya Roy","Rajat Sarkar","Souvik Chakraborty"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27869","url":"https://arxiv.org/abs/2608.27869","pdf":"https://arxiv.org/pdf/2608.27869.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Discovering governing partial differential equations (PDEs) from observational data remains a core challenge across the sciences. Existing sparse-regression, symbolic-regression, and LLM-based approaches can be constrained by predefined libraries, noise sensitivity, hallucination, or limited iterative refinement. We introduce \\textbf{MAGE} (\\textbf{M}ultimodal \\textbf{A}gentic \\textbf{G}overning \\textbf{E}quation Discovery), an agentic framework that organizes PDE discovery as a \\textit{confidence governed hypothesis validation loop} inspired by the scientific cycle of observation, hypothesis, and falsification. Four role-specialized agents collaborate: a \\textit{Differential Observer} computing derivatives and diagnostic visualizations; a VLM-powered \\textit{Phenomenology Extractor} distilling qualitative cues from multimodal diagnostics; an LLM-driven \\textit{Governing Law Synthesizer}"},{"title":"A Survey on Rubric-Guided Reinforcement Learning for Language Models","id":"arxiv:2608.27505","submittedDate":"2026-08-27","topics":["Post-Training","Evaluation","Alignment","Interpretability","RL for LLM"],"source":"arxiv","tags":["Post-Training","Evaluation","Alignment","Interpretability","RL for LLM"],"authors":["Zifei Shan","Fangning Shao"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27505","url":"https://arxiv.org/abs/2608.27505","pdf":"https://arxiv.org/pdf/2608.27505.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Reinforcement learning from human feedback (RLHF) has become the dominant paradigm for aligning large language models (LLMs) with human preferences. However, traditional RLHF relies on scalar reward signals that lack interpretability and fail to capture the multifaceted nature of response quality. Rubric-guided reinforcement learning addresses these limitations by introducing structured, interpretable evaluation criteria, or rubrics, as the backbone of reward design, feedback generation, and policy optimization. In this survey, we introduce a Bayesian framework that defines constitutions as prior distributions $P(R)$ over evaluation criteria and rubrics as conditional instantiations $R_x \\sim P(R|x)$. Under this unified view, we present a taxonomy of rubric-guided RL along the prior-posterior axis, covering constitutional AI, instance-specific rubrics, process-level supervision, self-evo"},{"title":"CommerceVibe: Learning to Design E-Commerce Creatives as Executable Visual Code via Dual-Feedback Reinforcement Learning","id":"arxiv:2608.27893","submittedDate":"2026-08-28","topics":["LLM Training","VLM Training","Evaluation","Fine-tuning","RL for LLM"],"source":"arxiv","tags":["LLM Training","VLM Training","Evaluation","Fine-tuning","RL for LLM"],"authors":["Yajiao Xu","Jin Zhang","Jiangbo Ai","Tao Jiang","Mo Xu","Lina Huang","Chengfu Huo"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27893","url":"https://arxiv.org/abs/2608.27893","pdf":"https://arxiv.org/pdf/2608.27893.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"High-quality e-commerce creatives are essential for presenting products and conveying marketing messages. Recent diffusion models enable scalable creative generation and produce visually compelling images, but their flattened raster outputs often contain distorted text and inconsistent product details, requiring refinement before deployment. Moreover, without explicit structure, the resulting creatives are difficult to edit and reuse, while complex design requirements remain challenging to encode as verifiable training signals. To address these challenges, we present CommerceVibe, which represents creatives as executable visual code and formulates generation as conditional HTML/CSS program synthesis. Given product images, design requirements, and product information, it produces renderable, editable, and reusable creatives. We further introduce dual-feedback reinforcement learning, in wh"},{"title":"Program Learning with Verifiable Rewards: Symbolic Backpropagation for Post-Training LLMs","id":"arxiv:2608.28421","submittedDate":"2026-08-28","topics":["Post-Training","Reasoning","Evaluation","RL for LLM"],"source":"arxiv","tags":["Post-Training","Reasoning","Evaluation","RL for LLM"],"authors":["Vishvesh Bhat"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.28421","url":"https://arxiv.org/abs/2608.28421","pdf":"https://arxiv.org/pdf/2608.28421.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Post training a language model to reason means updating its weights. Supervised finetuning and reinforcement learning both place the acquired capability inside the model where it cannot be inspected cannot be checked step by step and cannot be moved to another model. We argue that for tasks whose intermediate steps admit verification, reasoning is better placed outside the base models weights as an explicit program composed from deterministic and neural primitives. We introduce PLVR (Program Learning with Verifiable Rewards): a post training method that learns such programs directly from input-output examples. Its mechanism is symbolic backpropagation: each program layer carries a typed ontology a loss is computed at the output against ground truth and required input ontologies are propagated backward by type inference over primitive signatures: an analogue of the chain rule in which cre"},{"title":"Retrieving Relations, Detecting Fallacies: A RAG Approach to Political Debate Analysis","id":"arxiv:2608.27471","submittedDate":"2026-08-18","topics":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"source":"arxiv","tags":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"authors":["Deborah Dore","Greta Damo","Elena Cabrio","Serena Villata"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27471","url":"https://arxiv.org/abs/2608.27471","pdf":"https://arxiv.org/pdf/2608.27471.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Fallacies are arguments that employ invalid reasoning, making their automatic detection critical in sensitive contexts such as high-stakes political debates, where public opinion is shaped. Spotting a fallacious argument requires contextual knowledge beyond its pure surface text. This entails world knowledge pertaining to the subject matter under discussion, as well as knowledge of the relationships that exist between arguments within the argumentative discourse. Prior work on fallacy analysis has shown that argumentative discourse structure can beneficially improve classification performance. However, such structure is typically encoded only as static classifier features, limiting its flexibility. Building on this intuition while addressing this limitation, we introduce a guided retrieval-augmented methodology for fallacy detection and classification that leverages argumentative relatio"},{"title":"Finding Where the Buck Stops: An Automated Failure Attribution-Based Reflection Framework for Multi-Agent Collaboration","id":"arxiv:2608.28264","submittedDate":"2026-08-28","topics":["Error Attribution","Multi-Agent","Reasoning","Reflection"],"source":"arxiv","tags":["Error Attribution","Multi-Agent","Reasoning","Reflection"],"authors":["Xiaoqing Wang","Keman Huang","Bin Liang","Hongyu Li","Xiaoyong Du","Wuqiong Pan"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.28264","url":"https://arxiv.org/abs/2608.28264","pdf":"https://arxiv.org/pdf/2608.28264.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Multi-agent systems (MAS) powered by large language models have shown promise for complex tasks but suffer from high failure rates. Current self-reflection methods for MAS require all agents to reflect upon failure, overlooking a critical reality: failures typically stem from a specific agent leading the task astray, namely the decisive error agent, while others merely fulfill their regular duties. Forcing regular-behaving agents to reflect contaminates their memory with wrong insights. Hence, we propose DoCtOR (Diagnose-then-Correct PPO-enhanced Reflection), a novel reflection framework that enhances multi-agent collaboration. DoCtOR first identifies the decisive error step and decisive error agent through automated failure attribution, then employs counterfactual reasoning to generate a corrected decisive error step, and finally engages only the decisive error agent to produce targeted"},{"title":"Nemotron 3.5 Content Safety Moderator: A Compact Multimodal, Multilingual, and Reasoning Enabled Content Safety Moderator","id":"arxiv:2608.27548","submittedDate":"2026-08-27","topics":["Agent Safety","VLM Training","Reasoning","Evaluation"],"source":"arxiv","tags":["Agent Safety","VLM Training","Reasoning","Evaluation"],"authors":["Varun Singh","Anuj Doshi","Makesh Narsimhan Sreedhar","Shaona Ghosh","Katherine Luna"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27548","url":"https://arxiv.org/abs/2608.27548","pdf":"https://arxiv.org/pdf/2608.27548.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Safety moderation for deployed AI applications is moving beyond text-only prompts: systems increasingly need to judge images, documents, screenshots, and generated responses under policies that vary across domains. Existing guardrails usually cover only part of this setting, making it difficult to combine broad coverage, custom policy control, and low compute cost. We present Nemotron 3.5 Content Safety Moderator, also referred to as Nemotron 3.5 CS in this paper for brevity, a compact 4B vision-language safety moderator that jointly classifies user prompts, images, and assistant responses across 12 languages. Nemotron 3.5 CS returns safety labels for latency-sensitive moderation and can additionally produce concise reasoning traces that apply supplied custom policies and identify violated categories when reasoning is requested. We also release a multimodal and multilingual safety datase"},{"title":"WM-R1: Training GUI Agents to Reason and leverage World Models with Reinforcement Learning","id":"arxiv:2608.27508","submittedDate":"2026-08-27","topics":["Post-Training","Computer Use","Evaluation","World Model"],"source":"arxiv","tags":["Post-Training","Computer Use","Evaluation","World Model"],"authors":["Yu Han","Tianwen Qian"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27508","url":"https://arxiv.org/abs/2608.27508","pdf":"https://arxiv.org/pdf/2608.27508.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"GUI agents trained with reinforcement learning (RL) have showcased strong environment learning capabilities on mobile platforms. However, RL typically demands extensive real-environment interactions, leading to high resource costs and instability, especially in GUI scenarios. To address these, we propose WM-R1, the first reinforcement learning framework that trains mobile GUI agents with world models instead of real environments. Specifically, world models serve as the source of state transitions during all rollouts, replacing the real Android environment within the training loop. WM-R1 also embeds world models directly into the thinking process, enabling agents to reason about the consequences of candidate actions before committing to the final action. Crucially, WM-R1 eliminates the need for real-environment interaction, supports massively parallelized and step-level granularized traje"},{"title":"LLM-Based Agents for Software and Systems Security: Approaches, Applications, and Assessment","id":"arxiv:2608.28490","submittedDate":"2026-08-28","topics":["Reasoning","Planning","Reflection","Agent Framework"],"source":"arxiv","tags":["Reasoning","Planning","Reflection","Agent Framework"],"authors":["Jingjing Nie","Jiawei Guo","Krishna Meda","Haipeng Cai"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.28490","url":"https://arxiv.org/abs/2608.28490","pdf":"https://arxiv.org/pdf/2608.28490.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Software and systems security workflows are typically procedural: analysts inspect heterogeneous artifacts, form hypotheses, invoke tools, interpret outputs, and revise plans. Large language model (LLM)-based agents, which can plan, use tools, retain state, and revise actions across multi-step workflows, are being rapidly adopted to automate this work. Given the consequences of delegating security decisions to autonomous systems, understanding how such agents are built, used, and assessed is crucial. Yet to this date, there remains a lack of systematic understanding of what has been done and how far we are in this field: the term \"agent\" is applied inconsistently, applications differ sharply in risk, and assessment protocols are often incomparable. To gain a comprehensive and coherent view of this area hence inform relevant future research, this paper provides a systematic literature rev"},{"title":"Dynamic Alignment Compensation for Hallucination Mitigation in Large Vision-Language Models","id":"arxiv:2608.28058","submittedDate":"2026-08-28","topics":["VLM Training","Hallucination","Evaluation","Alignment"],"source":"arxiv","tags":["VLM Training","Hallucination","Evaluation","Alignment"],"authors":["Kairong Yu","Zixin Zhu","Le Yu","Hongwei Wang"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.28058","url":"https://arxiv.org/abs/2608.28058","pdf":"https://arxiv.org/pdf/2608.28058.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Large Vision-Language Models (LVLMs) remain prone to hallucinations, producing responses that are irrelevant or inconsistent with the multimodal input. Existing mitigation methods mainly rely on external supervision, output calibration, or attention regulation, leaving the internal representation dynamics of autoregressive generation underexplored. We identify an inference-time failure mode in which cross-modal representations degrade across decoder layers and drift across generation steps, destabilizing token prediction and increasing hallucination risk. We propose \\emph{Dynamic Alignment Compensation} (DAC), a training-free inference-time method that detects representation divergence and selectively applies lightweight residual compensation. DAC combines Layer-wise Semantic Compensation to mitigate inter-layer degradation with Sequential Semantic Correction to constrain temporal drift."},{"title":"PHR-VLA: Planning Horizon Reasoning for Vision-Language-Action Models","id":"arxiv:2608.27609","submittedDate":"2026-08-27","topics":["VLM Training","Reasoning","Planning","Alignment"],"source":"arxiv","tags":["VLM Training","Reasoning","Planning","Alignment"],"authors":["Davood Soleymanzadeh","Kaidi Zhang","Zhiyuan Zhang","Bihao Zhang","Xiao Liang","Yu She","Minghui Zheng"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27609","url":"https://arxiv.org/abs/2608.27609","pdf":"https://arxiv.org/pdf/2608.27609.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Vision-language-action models (VLAs) have shown strong promise for general-purpose robotic manipulation by mapping language instructions and vision observations directly to actions. However, most VLAs primarily condition action prediction on current observations and lack an explicit mechanism for reasoning over future task dynamics, which is particularly important for fine-grained, contact-rich manipulation. We present PHR-VLA, a framework that enables planning-horizon reasoning in VLAs through privileged latent representations of future dynamics. PHR-VLA introduces a lightweight auxiliary future head that, during training, aligns the VLA's internal representations with latent dynamics extracted from future observations. Evaluation results demonstrate that local, contact-centric, patch-level latent dynamics supervision from the wrist camera improves success rate on LIBERO from 84.1% to 8"},{"title":"Acquire, Repair, Preserve: A Diagnosis-Guided Post-Training Recipe for Small-Model Dialogue Game Agents","id":"arxiv:2608.28458","submittedDate":"2026-08-28","topics":["Post-Training","LLM Training","Evaluation","Fine-tuning"],"source":"arxiv","tags":["Post-Training","LLM Training","Evaluation","Fine-tuning"],"authors":["Nan Li"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.28458","url":"https://arxiv.org/abs/2608.28458","pdf":"https://arxiv.org/pdf/2608.28458.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Interactive dialogue games test a capability that static benchmarks largely leave implicit: a model must carry state across turns, interpret feedback, and choose valid actions under changing constraints. We study this setting in the LM Playschool Challenge with a 2B open-weight model, and find that many failures are not only broad knowledge failures but also local decision failures: repeated guesses, malformed actions, and violations of feedback that the model has just seen. These diagnostics motivate a training recipe organized around three steps: acquire broad game participation through supervised fine-tuning, repair mechanically verifiable failures within one targeted dialogue-game family using turn-local preference pairs, and preserve general capabilities beyond these dialogue games. In the official final evaluation, our submission improves public clemscore from 10.67 to 38.92 and cl"},{"title":"Synth-JDoc: Synthesizing a Japanese Document Image Dataset for OCR with Diverse Layouts and Embedded Images","id":"arxiv:2608.28248","submittedDate":"2026-08-28","topics":["VLM Training","Evaluation","Fine-tuning","Data Engine"],"source":"arxiv","tags":["VLM Training","Evaluation","Fine-tuning","Data Engine"],"authors":["Keito Sasagawa","Shuhei Kurita","Daisuke Kawahara"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.28248","url":"https://arxiv.org/abs/2608.28248","pdf":"https://arxiv.org/pdf/2608.28248.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"The ability of Large Vision Language Models (LVLMs) to read text within document images is crucial, as it enables various applications such as Document Visual Question Answering. To enhance the text-reading capabilities of LVLMs, high-quality OCR datasets are essential. This need is particularly critical for Japanese documents, which often feature vertically written text alongside horizontally written text. Current LVLMs demonstrate considerably lower performance on vertically written Japanese text than on horizontally written text, necessitating specialized OCR datasets to bridge this gap. However, manually constructing OCR datasets is expensive and difficult to scale. Alternatively, constructing datasets by extracting text from existing document images using OCR models introduces challenges, such as text recognition errors and the prerequisite of sourcing document images. To address th"},{"title":"Post-Training VLMs for Video Mistake Detection","id":"arxiv:2608.28406","submittedDate":"2026-08-28","topics":["Post-Training","LLM Training","Evaluation","Fine-tuning"],"source":"arxiv","tags":["Post-Training","LLM Training","Evaluation","Fine-tuning"],"authors":["Federico Spurio","Olga Zatsarynna","Lars Doorenbos","Emad Bahrami","Gianpiero Francesca","Juergen Gall"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.28406","url":"https://arxiv.org/abs/2608.28406","pdf":"https://arxiv.org/pdf/2608.28406.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Human mistakes are inevitable when following instructions, yet they can lead to severe consequences. As such, there has been an increased interest in developing methods for detecting mistakes in videos, with current methods mostly focusing on closed-set protocols. While successful in controlled settings, the closed-set assumption limits their wider applicability, as any changes to the task require collecting new data and re-training models. Instead, we argue that mistake detection methods should learn the general concept of a mistake, rather than overfitting to step-specific details. To reflect this, we introduce the Mistake Detection Video Question Answering (MD-VQA) protocol and accompanying benchmark. MD-VQA tests whether methods can discern if a step was executed correctly with respect to its description, for both seen and unseen actions. To address this important challenge, we propo"},{"title":"What Can Low Resource Languages Learn From Each Other?","id":"arxiv:2608.27753","submittedDate":"2026-08-27","topics":["LLM Training","VLM Training","Evaluation","Fine-tuning"],"source":"arxiv","tags":["LLM Training","VLM Training","Evaluation","Fine-tuning"],"authors":["Achyuth P","Kahaan Shah","Chetan Arora"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27753","url":"https://arxiv.org/abs/2608.27753","pdf":"https://arxiv.org/pdf/2608.27753.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Despite the rapid advancement of Vision-Language Models (VLMs), their linguistic reach remains largely confined to high-resource languages, leaving the majority of the world's 7,000+ living languages on the wrong side of a growing digital divide. This disparity is especially pronounced in Optical Character Recognition (OCR), where low-resource scripts lack the massive datasets required for traditional scaling laws. We investigate OCR adaptation in extreme data-scarce regimes (<10K real and <250K synthetic images), demonstrating that conventional fine-tuning strategies often reach a performance ceiling. Our key finding reveals a structural inefficiency in language-specific adaptation: while higher layers of specialized models diverge to capture unique script nuances, the lower layers learn redundant, highly similar features. Motivated by this observation, we propose PSMC (Pre-train, Speci"},{"title":"AcCoRD: Evaluating User-Agent Collaboration Under Realistic User Preference Dynamics","id":"arxiv:2608.27818","submittedDate":"2026-08-28","topics":["Multi-Agent","Planning","Evaluation"],"source":"arxiv","tags":["Multi-Agent","Planning","Evaluation"],"authors":["Tejas Srinivasan","Shikib Mehri","Nandita Shankar Naik","Anirban Das","William M. Campbell","Jesse Thomason"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27818","url":"https://arxiv.org/abs/2608.27818","pdf":"https://arxiv.org/pdf/2608.27818.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"User preferences in user-agent collaboration are rarely static and fully-specified upfront: preferences are formed, revealed, adjusted, and relaxed during interaction. Existing benchmarks for evaluating user-agent collaboration focus almost exclusively on resolving underspecified preferences, thereby failing to capture the richer dynamics of real-world interaction. We introduce AcCoRD, a user-agent collaboration benchmark requiring agents to handle diverse user preference dynamics in two domains: online shopping and travel planning. We evaluate five frontier LLMs under two prompting strategies: vanilla ReAct, and an uncertainty-guided variant that prompts models to identify and resolve ambiguity about user preferences. Our results reveal that frontier models can handle underspecification but struggle to satisfy preferences that emerge or evolve mid-interaction and require more sophistica"},{"title":"When Evidence Shapes Collaboration: Knowledge-Conditioned Topology Generation for Multi-Agent Systems","id":"arxiv:2608.27984","submittedDate":"2026-08-28","topics":["Multi-Agent","Evaluation","Alignment"],"source":"arxiv","tags":["Multi-Agent","Evaluation","Alignment"],"authors":["Yangxiao Jiang","Jiarun Fan","Mingcong Xu","Yanxi Guo","Jiwen Feng","Shanqing Xu","Mengchen Qian","Wei Chen","Xiaojin Zhang"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27984","url":"https://arxiv.org/abs/2608.27984","pdf":"https://arxiv.org/pdf/2608.27984.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Multi-Agent Systems (MAS) have recently moved from static workflows toward dynamically generated collaboration topologies. However, existing topology generation methods rely primarily on the parametric knowledge of large language models, with external search or retrieval used only as a reactive tool rather than an explicit determinant of collaboration structure. This leads to structure-knowledge misalignment, where systems exhibit redundant interactions or insufficient verification in knowledge-intensive tasks. We propose K-GAT (Knowledge-Guided Agent Topology Generator), a neuro-symbolic framework that formulates collaboration topology design as a knowledge-conditioned structure learning problem, integrating external evidence directly into autoregressive graph generation. Extensive experiments on knowledge-intensive benchmarks demonstrate K-GAT's efficiency and effectiveness: notably on"},{"title":"LongGuard: Mechanistic Analysis and Training-Free Mitigation of Long-Context Failure in Safety Guardrails","id":"arxiv:2608.27580","submittedDate":"2026-08-27","topics":["Reasoning","Evaluation","Data Engine"],"source":"arxiv","tags":["Reasoning","Evaluation","Data Engine"],"authors":["Ziyang Chen","Xing Wu","Songlin Hu"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27580","url":"https://arxiv.org/abs/2608.27580","pdf":"https://arxiv.org/pdf/2608.27580.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Safety guardrails serve as the last line of defense against harmful inputs and outputs of large language models (LLMs), yet they are trained and evaluated almost exclusively on short text. We present LongGuard, a framework that evaluates, mechanistically analyzes, and mitigates long-context guardrail failure. We formulate the task as Safety Needle-in-a-Haystack (SafetyNIAH) over a 0.25k-32k length grid; across 15 mainstream guardrails, unsafe recall drops monotonically by more than 50% on average, and a paired Benign-Fill vs. Needle-Repeat design attributes the failure to proportional dilution of the unsafe needle rather than to absolute length. A three-layer attention-logit-behavior analysis on six guardrails locates the mechanism: attention mass on the unsafe needle is diluted, the unsafe-over-safe logit margin is compressed in lockstep, and the detection decision collapses accordingly"},{"title":"COVER: Identifiable Evaluation of Coalition Routing","id":"arxiv:2608.28475","submittedDate":"2026-08-28","topics":["Agent Safety","Multi-Agent","Evaluation"],"source":"arxiv","tags":["Agent Safety","Multi-Agent","Evaluation"],"authors":["Raghul Sugumar","Amrit Gopinath"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.28475","url":"https://arxiv.org/abs/2608.28475","pdf":"https://arxiv.org/pdf/2608.28475.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"When a multi-agent system changes its team, it also changes the messages and final answer it produces, so an end-to-end accuracy gap does not by itself identify a routing effect. We introduce method, an evaluation contract that fixes a public information boundary, downstream stack G, and finite legal team family before outcomes are generated. Complete coverage identifies exact finite-benchmark oracle regret conditional on that stack. For any finite collection of frozen policies, executing the union of their distinct selected teams is the minimal assumption-free support for every pairwise policy contrast, though not for absolute oracle regret. Two controlled tables with source-ID-disjoint splits test the instrument. On MuSiQue-12, a pre-specified privileged positive control improves regret from 0.532 to 0.402; a later public-interface control reaches 0.424 versus 0.554 but is retrospectiv"},{"title":"openJiuwen: Beyond Static Harnesses for Long-Horizon Coding Agents","id":"arxiv:2608.27969","submittedDate":"2026-08-28","topics":["Multi-Agent","Code Agent","Evaluation"],"source":"arxiv","tags":["Multi-Agent","Code Agent","Evaluation"],"authors":["openJiuwen Team","Tao Yu","Xinyu Zhang","Qianqian Chen","Xiaoneng Xiang","Chia Kwangyang","Xingchen Huang","Ran Chen","Yangkai Ding","Zheng Wang","Yeo Boon Hong","Bingzheng Gan","Enrui Hu","Shuo Cheng","Deyang Li","Ruifeng Shi","Hongbo Wang","Qi Ye","Xuefeng Jin","Zhangchun Zhao"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27969","url":"https://arxiv.org/abs/2608.27969","pdf":"https://arxiv.org/pdf/2608.27969.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Long-horizon coding agents operate over evolving repository states while increasingly relying on heterogeneous capabilities, delegated agents, and multi-agent coordination. These trends pose two complementary challenges for the agent harness. First, developers need to compose capabilities, reconfigure execution logic, and scale increasingly complex agent systems without repeatedly rebuilding orchestration. Second, complex coding tasks continuously produce new evidence---such as semantic diagnostics, execution outcomes, task progress, and changing context relevance---that should dynamically influence subsequent runtime decisions. We characterize these challenges as Structural Composability and Runtime Adaptivity. We present openJiuwen, an open-source harness designed for both developer composability and adaptive task execution. openJiuwen provides a shared execution substrate and Rail-bas"},{"title":"Class-Based Heuristic Selection for Solving the Flying Block Puzzle","id":"arxiv:2608.27476","submittedDate":"2026-08-20","topics":["Multi-Agent","Planning","Evaluation"],"source":"arxiv","tags":["Multi-Agent","Planning","Evaluation"],"authors":["Sanyar Ahmadi","Pedram Asadzadeh","Amanj Khorramian"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27476","url":"https://arxiv.org/abs/2608.27476","pdf":"https://arxiv.org/pdf/2608.27476.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Heuristic search underlies planning in autonomous systems ranging from warehouse logistics to robotic navigation, yet generic heuristics fail to exploit the structural constraints that govern constrained spatial domains, causing search performance to degrade catastrophically on harder instances. We study this problem through the two-column Flying Block Puzzle, a rigorously NP-complete spatial planning microworld whose bottleneck geometry mirrors clearance-to-size constraints encountered in multi-agent path finding, autonomous vehicle navigation, and block relocation systems. We introduce the Class-Based Heuristic A* (CBHA*) algorithm, which integrates a General Move Constraint to capture minimum displacement costs when vacant units are scarce, a formal kinematic taxonomy partitioning the state space into seven mutually exclusive classes with provably admissible heuristics based on vacanc"},{"title":"AGENT-O: A Semantic Agent Card Framework for Interoperable and Governed Healthcare AI Agents","id":"arxiv:2608.28345","submittedDate":"2026-08-28","topics":["Reasoning","Evaluation","Alignment"],"source":"arxiv","tags":["Reasoning","Evaluation","Alignment"],"authors":["Pengze Li","Cui Tao"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.28345","url":"https://arxiv.org/abs/2608.28345","pdf":"https://arxiv.org/pdf/2608.28345.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"AGENT-O is a modular ontology framework that defines a semantic Agent Card for representing health-oriented AI agent systems and supports assessment of reporting completeness in scientific publications. AGENT-O was developed as an OWL 2/RDF ontology covering runtime, models, workflow, tools, clinical use, evaluation, provenance, governance, and reporting assessment. Evaluation included ontology inventory, OWL-RL reasoning, three SHACL suites, 12 SPARQL competency queries, three cases, and model-assisted reporting-completeness assessment of 279 papers across five dimensions. The ontology contained 1,962 RDF triples and 1,922 Protege axioms, with 252 active classes, 198 active object properties, and 51 datatype properties. All SHACL suites conformed on example graphs, all competency queries returned prespecified evidence, and all 279 papers were scored. Incomplete reporting was highest for"},{"title":"Gen-TAS: A Generative AI-Aided Hardware-Software Task Allocation Framework for FPGA-GPP Heterogeneous Systems","id":"arxiv:2608.28160","submittedDate":"2026-08-28","topics":["Agentic RAG","Agentic Search","Reasoning"],"source":"arxiv","tags":["Agentic RAG","Agentic Search","Reasoning"],"authors":["Mary Kong","Yuqin Zhao","Semih Vazgecen","Cristian Sestito","Themis Prodromakis"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.28160","url":"https://arxiv.org/abs/2608.28160","pdf":"https://arxiv.org/pdf/2608.28160.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"FPGA-GPP heterogeneous systems combine software flexibility with the performance and energy efficiency of reconfigurable hardware. However, determining which application tasks should execute on the GPP or FPGA requires extensive expertise and design-space exploration, particularly when user objectives vary across latency, communication, resource utilisation, and power. This paper proposes Gen-TAS, a knowledge-grounded LLM framework for user-specific FPGA-GPP task allocation. By combining task-graph analysis with RAG, Gen-TAS grounds LLM reasoning in historical implementation knowledge and generates multiple explainable strategies tailored to the specified objectives. Human-in-the-loop selection and a deterministic backend connect LLM-generated decisions to reproducible FPGA SoC implementations. Experiments on CNN and SDR workloads across multiple LLMs demonstrate stable, requirement-driv"},{"title":"Quantization-Triggered Backdoors in Language Models: Cross-Quantizer Transferability and the Validation--Deployment Gap","id":"arxiv:2608.27512","submittedDate":"2026-08-27","topics":["Post-Training","Evaluation","Fine-tuning"],"source":"arxiv","tags":["Post-Training","Evaluation","Fine-tuning"],"authors":["Jacopo Dardini","Claudio Stanzione","Giordano Colò","Giuseppe Fenza"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27512","url":"https://arxiv.org/abs/2608.27512","pdf":"https://arxiv.org/pdf/2608.27512.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Post-training quantization is often treated as a semantically neutral optimization for edge deployment of Large Language Models. When a full-precision source checkpoint is evaluated and quantization is applied downstream without equivalent re-evaluation, this workflow creates a structural validation--deployment gap: because quantization is a many-to-one mapping over parameter space, source-precision certification does not guarantee behavioral equivalence in the deployed configuration. We formalize this gap through Quantization Behavioral Equivalence Classes (QBECs) and prove that QBEC membership does not imply behavioral equivalence, providing a theoretical basis for quantization-triggered backdoor attacks. Building on a three-stage adversarial fine-tuning framework, we embed latent malicious payloads into models that satisfy the source-precision checks used in our evaluation, yet activa"},{"title":"XHotpotQA: A Benchmark for Cross-Lingual Knowledge Composition in Multi-Hop Question Answering","id":"arxiv:2608.27481","submittedDate":"2026-08-23","topics":["Reasoning","Evaluation","Alignment"],"source":"arxiv","tags":["Reasoning","Evaluation","Alignment"],"authors":["Iman Barati","Arash Ghafouri","Behrouz Minaei-Bidgoli"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27481","url":"https://arxiv.org/abs/2608.27481","pdf":"https://arxiv.org/pdf/2608.27481.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Knowledge-intensive multi-hop question answering requires systems to select evidence and compose dependent facts, yet multilingual benchmarks usually translate an entire example into one language. This hides failures at language boundaries inside the reasoning chain. We introduce XHotpotQA, a controlled benchmark for cross-lingual knowledge composition over mixed-language evidence. Each instance is modeled as an evidence-dependency graph whose question, bridge evidence, answer-bearing evidence, and distractors have explicit language assignments. The audited resource contains 15,661 training and 7,405 validation instances, with sentence-level support supervision and supplied distractors. In validation, 99.81% of items cross the question-to-gold-evidence language interface and 95.60% use gold paragraphs in different languages. Across three reader artifacts, full question-evidence mismatch "},{"title":"On the Maintenance and Co-evolution of Agent Plugins: An Empirical Study of Claude Code Plugin Marketplaces","id":"arxiv:2608.28497","submittedDate":"2026-08-28","topics":["Tool Use","Reasoning","Code Agent"],"source":"arxiv","tags":["Tool Use","Reasoning","Code Agent"],"authors":["Ahmed Hereiz","Yingzhe Lyu","Hao Li","Bram Adams","Ahmed E. Hassan"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.28497","url":"https://arxiv.org/abs/2608.28497","pdf":"https://arxiv.org/pdf/2608.28497.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"AI coding agents, software tools that automate development tasks through reasoning and tool use, are increasingly extended through plugin marketplaces, yet the structure, maintenance, and co-evolution dynamics of these emerging repositories remain empirically unexplored. Unlike traditional software packages that deliver functionality through source code, agent plugins deliver functionality through a combination of natural-language instruction files, scripts, and configuration files, raising the question of whether these plugins are maintained artifacts that co-evolve across components, or one-off artifacts that developers write once and do not need to revisit. To study the maintenance and co-evolution of agent plugins, we conduct an empirical study of 1,926 repositories hosting Claude Code plugin marketplaces, analyzing 8,351 plugins and 77,773 commits across 2,018 marketplaces. We find "},{"title":"LongPIBench: A Long-Context Benchmark for Prompt Injection","id":"arxiv:2608.28411","submittedDate":"2026-08-28","topics":["Agent Safety","Evaluation","Data Engine"],"source":"arxiv","tags":["Agent Safety","Evaluation","Data Engine"],"authors":["Yupei Liu","Yuqi Jia","Neil Zhenqiang Gong","Jinyuan Jia"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.28411","url":"https://arxiv.org/abs/2608.28411","pdf":"https://arxiv.org/pdf/2608.28411.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Prompt injection attacks pose a serious security risk to large language models in real-world applications. However, existing prompt injection benchmarks primarily focus on short-context inputs, leaving the attacks and defenses in long-context settings largely unexplored. This gap leads to a substantial overestimation of the effectiveness of current defenses. In this paper, we bridge the gap by introducing LongPIBench, a long-context benchmark for prompt injection covering 4 realistic application scenarios: paper peer review, resume screening, code review, and email summary. For each scenario, we construct a synthetic dataset and a real-world dataset, with context lengths ranging from thousands to tens of thousands of tokens. The evaluation results on LongPIBench reveal significant vulnerabilities of prompt injection defenses under long-context settings: even simple heuristic prompt injec"},{"title":"DAMP: Decay-Aware Mixed-Precision Recurrent-State Quantization","id":"arxiv:2608.27513","submittedDate":"2026-08-27","topics":["Post-Training","Reasoning","Evaluation"],"source":"arxiv","tags":["Post-Training","Reasoning","Evaluation"],"authors":["Tao Zhang","Jianchao Tan","Pingwei Sun","Yanqi Yu","Zixu Jiang","Yuchen Xie","Xunliang Cai","Ziqian Zeng"],"upvotes":0,"arxiv":"https://arxiv.org/abs/2608.27513","url":"https://arxiv.org/abs/2608.27513","pdf":"https://arxiv.org/pdf/2608.27513.pdf","date":"2026-08-31","announceDate":"2026-08-31","abstract":"Softmax attention stores key and value vectors for every preceding token, causing inference memory to grow with sequence length. Recent language models incorporating Gated DeltaNet (GDN) or Kimi Delta Attention (KDA) reduce this cost by replacing the KV cache in most layers with fixed-size recurrent states. However, these recurrent states are commonly stored in FP32 and consume substantial GPU memory; their updates are memory-bandwidth bound and contribute significantly to decoding latency. To our knowledge, we are the first to study post-training quantization of recurrent states in GDN and KDA based language models. We find that uniform quantization provides a poor accuracy--storage trade-off: INT8 and FP8 already degrade accuracy on complex reasoning tasks, while INT4 and NVFP4 reduce it to near zero. We further find that most quantization-error energy is concentrated in a small subset"}],"archive":[],"latestPath":"data/latest.json"};
